   "url": "https://www.pciconcursos.com.br/noticias/ipam-de-porto-velho-ro-abre-concurso-publico-com-salarios-de-ate-5000",
   "orgao": "IPAM - Instituto de Previdência e Assistência dos Servidores do Município de Porto Velho",
   "manchete": "IPAM de Porto Velho - RO abre concurso público com salários de até R$ 5.000,00",
   "uf": "RO",
   "vagas": 71,
   "cadastroReserva": false,
   "salarioMax": 5000,
   "porHora": false,
   "cargos": "Técnico Autárquico, Analista Autárquico",
